arguments.command:
cd /workspace/submission && python3 - << 'PY'
src = open('engine.hpp').read()
src = src.replace("""// --------------------------------------------------------- image geometry

const int WIDTH[3] = {16, 8, 4};
const int LANES[3] = {4, 8, 16};""",
"""// --------------------------------------------------------- image geometry
//
// Every record starts on a 64-byte boundary and holds a 32-byte fixed
// header (kind, mode, cached, reserved, lo, span, count, reserved,
// allocated bytes, 16-byte base = starts[lo]) followed by its payload:
// child offsets then separator keys for an internal node, all covered
// run starts for a leaf.  Key payload widths are [16,8,4] bytes for
// modes [0,1,2]; mode 0 stores absolute keys while modes 1 and 2 store
// key-base, which is legal only when every covered run start satisfies
// the corresponding 2^64 / 2^32 range test.  The hop array follows the
// last record, padded with zeros to a 64-byte multiple.

const int WIDTH[3] = {16, 8, 4};
const int LANES[3] = {4, 8, 16};""")
src = src.replace("""// --------------------------------------------------------- packed lookup

struct Answer {""",
"""// --------------------------------------------------------- packed lookup
//
// Descent uses only the image bytes.  At an internal node the child
// index is the number of separator keys not exceeding the destination
// (equality goes right); at a leaf the greatest stored start not
// exceeding the destination selects the run and its hop-array entry.

struct Answer {""")
open('engine.hpp','w').write(src)
PY
g++ -O2 -std=c++17 -Wall -Wextra engine.cpp -o /workspace/tmp/engine && echo BUILD_OK && cd /workspace/examples && for f in *.in.native; do /workspace/tmp/engine < $f | diff ${f/.in./.out.} - > /dev/null && echo "PASS $f" || echo "FAIL $f"; done
